#!/bin/bash
set -eo pipefail
umask 077
test "$(id -un)" = sunyiq
for parent in / /data1 /data1/home /data1/home/sunyiq; do
  test -d "$parent"
  test ! -L "$parent"
  test "$(readlink -e "$parent")" = "$parent"
done
test ! -e '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001'
test ! -L '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001'
mkdir '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001'
mkdir '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/src' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/contracts' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/logs'
set -o noclobber
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/src/capture_rejected_header_v1.py'
printf '%s  %s\n' 'e3459ea7d3d8f2ce4fb8d1c67852357aa266b9458fd5e64721bd2775fc1579f8' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/src/capture_rejected_header_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/src/probe_us_input_headers_v1.py'
printf '%s  %s\n' '504b39f6485200b39dccc0f968b410a5f41936ac5081ac551c460d13a92cc835' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/src/probe_us_input_headers_v1.py' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/contracts/DIAGNOSIS_INPUT_v1.json'
printf '%s  %s\n' 'ab25fd027efc4da81d6659cad025788c39e794acd0e608e3954ee9b6674abe3c' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/contracts/DIAGNOSIS_INPUT_v1.json' | sha256sum -c -
printf '%s' '' | base64 -d > '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/input_headers_v1.sbatch'
printf '%s  %s\n' 'ca628361a78e5843b59b6d249baca9017de57af1df44534cb08bf79385e7e234' '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/input_headers_v1.sbatch' | sha256sum -c -
job=$(sbatch --parsable '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/input_headers_v1.sbatch')
case "$job" in ''|*[!0-9]*) exit 1;; esac
printf '%s\n' "$job" > '/data1/home/sunyiq/us_header_format_diagnosis_20261007_001/job_id.txt'
printf 'INPUT_HEADER_ROOT=/data1/home/sunyiq/us_header_format_diagnosis_20261007_001\nINPUT_HEADER_JOB_ID=%s\nINPUT_HEADER_SUBMITTED_ONCE\n' "$job"
